fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
// ...
self.shared_state.waker.register(cx.waker());
let id = get_id();
self.shared_state.id.set(id);
let buf: &[u8] = self.shared_state.buf.as_ref();
let write_e =
opcode::Write::new(types::Fd(self.fd), buf.as_ptr(), buf.len() as u32)
.build()
.user_data(id);
self.shared_state.sqes.set([write_e]);
SQE_SENDER.send(self.shared_state.clone());
return Poll::Pending;
}
